<script setup lang="tsx">
import { computed, onMounted, ref } from "vue";
import { useCurrentInstance } from "@/util";
import { GetCommonErrorCode, GetEllipsisText, ShowErrorTips } from "@/util/tips";
import { GetContentRencently } from "@/apis/contest.ts";
import { ContestRemoteList } from "@/types/contest.ts";
import type { TableRowData, TNodeReturnValue } from "tdesign-vue-next";
import type { CellParams } from "@/types/table";
import { useBreakpoint } from "@/composables/useBreakpoint";

const { globalProperties } = useCurrentInstance();
const { isMobile } = useBreakpoint();

// 说明：tdesign 的 BaseTableCol<T> 是递归类型（children?: BaseTableCol<T>[]），本页 cell 返回 JSX，
// 直接标注会触发 TS2589（Type instantiation is excessively deep），故按其字段构造一个非递归的等价列类型
type ContestRencentlyColumn = {
  title: string;
  colKey: string;
  cell?: (_h: unknown, data: CellParams<TableRowData>) => TNodeReturnValue;
};

const listColumns = ref<ContestRencentlyColumn[]>([
  {
    title: "来源",
    colKey: "source",
  },
  {
    title: "标题",
    colKey: "title",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      const text = GetEllipsisText(data.row.title, 25);
      return (
        <t-tooltip content={data.row.title}>
          <t-button variant="text" onClick={() => window.open(data.row.link, "_blank")}>
            {text}
          </t-button>
        </t-tooltip>
      );
    },
  },
  {
    title: "类型",
    colKey: "type",
  },
  {
    title: "开始时间",
    colKey: "start_time",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      return new Date(data.row.start_time).toLocaleString();
    },
  },
  {
    title: "结束时间",
    colKey: "end_time",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      return new Date(data.row.end_time).toLocaleString();
    },
  },
  {
    title: "时长",
    colKey: "duration",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      const startTime = data.row.start_time;
      const endTime = data.row.end_time;
      const duration = Date.parse(endTime) - Date.parse(startTime);
      return `${Math.round((duration / (1000 * 60) / 60) * 10) / 10} 小时`;
    },
  },
  {
    title: "状态",
    colKey: "status",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      if (data.row.status === "进行中") {
        return (
          <t-tag theme="success" variant="light">
            {data.row.status}
          </t-tag>
        );
      } else if (data.row.status === "已结束") {
        return (
          <t-tag theme="danger" variant="light">
            {data.row.status}
          </t-tag>
        );
      } else {
        return (
          <t-tag theme="warning" variant="light">
            {data.row.status}
          </t-tag>
        );
      }
    },
  },
]);

const dataLoading = ref(false);

const contestViews = ref<ContestRemoteList[]>();

const visibleColumns = computed(() => {
  if (isMobile.value) {
    return listColumns.value.filter((col) => col.colKey !== "end_time");
  }
  return listColumns.value;
});

const fetchData = async () => {
  dataLoading.value = true;
  try {
    const res = await GetContentRencently();
    if (res.code === 0) {
      contestViews.value = res.data as ContestRemoteList[];
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowErrorTips(globalProperties, GetCommonErrorCode());
  } finally {
    dataLoading.value = false;
  }
};

onMounted(async () => {
  await fetchData();
});
</script>

<template>
  <t-row>
    <t-col :span="isMobile ? 12 : 9">
      <t-card style="margin: 10px">
        <div style="overflow-x: auto; width: 100%">
          <t-table
            :data="contestViews"
            :columns="visibleColumns"
            row-key="title"
            vertical-align="top"
            :hover="true"
            :loading="dataLoading"
            table-layout="auto"
            :size="isMobile ? 'small' : 'medium'"
            style="white-space: nowrap"
          />
        </div>
      </t-card>
    </t-col>
    <t-col :span="isMobile ? 12 : 3">
      <t-card class="sh-card" header="近期比赛" :header-bordered="true">
        <p>来源于热门平台近期所举办的比赛，数据定期更新。</p>
      </t-card>
    </t-col>
  </t-row>
</template>

<style scoped>
.sh-card {
  margin: 10px;
}
</style>
